#include <bits/stdc++.h>
using namespace std;
#define INF (int)1e+9

int main(void) {
	int n,m,ans;
	cin>>n>>m;
	vector<string> s(n);
	for(int i=0;i<n;i++)cin>>s[i];

	vector<int> dp0(n,INF),dp1(n,INF);
	dp0[0]=0;
	for(int i=1;i<n;i++){
		for(int j=1;j<=min(m,i);j++){
			if(s[i-j][j-1]=='1')dp0[i]=min(dp0[i],dp0[i-j]+1);
		}
	}
	dp1[n-1]=0;
	for(int i=n-2;i>=0;i--){
		for(int j=1;j<=min(m,n-1-i);j++){
			if(s[i][j-1]=='1')dp1[i]=min(dp1[i],dp1[i+j]+1);
		}
	}

	for(int k=1;k<n-1;k++){
                ans=INF;
		for(int i=max(k-m+1,0);i<k;i++){
			for(int j=k+1;j<min(n,i+m+1);j++){
				if(s[i][j-i-1]=='1')ans=min(ans,dp0[i]+dp1[j]+1);
			}
		}
                if(ans==INF)cout<<-1;
		else cout<<ans;
		if(k<(n-2))cout<<" ";
		else cout<<endl;
	}	
	return 0;
}

#include <iostream>
#include <vector>
#include <string>

int main() {
    using namespace std;

    unsigned N, M;
    cin >> N >> M;
    vector<string> teleporter(N);
    for (auto &&S : teleporter)cin >> S;

    // x = min(x, y)
    const auto chmin{[](auto &&x, const auto &y) { if (x > y) x = y; }};

    // dp_1[i] := i から N まで最低何回のテレポートで到達できるか
    // dp_0[i] := 1 から i まで最低何回のテレポートで到達できるか
    // dp テーブルの要素はたかだか N - 1 なので、N を INF として用いてよい
    vector<unsigned> dp_1(N, N), dp_0(N, N);

    // dp_1[N] = 0 (1-indexed)
    // N から降順に dp テーブルを埋める
    dp_1.back() = 0;
    for (unsigned i = N; --i;)
        for (unsigned j = 0; j < M; ++j)
            if (teleporter[i][j] == '1')
                chmin(dp_1[i], dp_1[i + j + 1] + 1);

    // dp_0[1] = 0 (1-indexed)
    // 1 から昇順に dp テーブルを埋める
    dp_0.front() = 0;
    for (unsigned i = 0; i + 1 < N; ++i) {
        auto ans = N;
        for (unsigned j = 0; j < M; ++j) {
            // i からテレポートする遷移を計算する前に i + j へ到達可能
            // ⇔ i を通らずに i + j へ到達可能
            if (i + j + 1 < N && dp_0[i + j + 1] < N)
                chmin(ans, dp_1[i + j + 1] + dp_0[i + j + 1]);
            if (teleporter[i][j] == '1')
                chmin(dp_0[i + j + 1], dp_0[i] + 1);
        }
        if (i) {
            if (ans < N) cout << ans << " ";
            else cout << "-1 ";
        }
    }
    cout << endl;

    return 0;
}
